//! Identity-preserving checked Attr transfer into inert Element sources.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><div id=mount></div><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://inert-attachment.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}

#[test]
fn inert_foreign_attribute_actual_namespace_case_prefix_alias_clone_and_observation(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xml=document.implementation.createDocument('urn:element','e:Root'),root=xml.documentElement,plain=xml.createElement('Other'),html=xml.createElementNS('http://www.w3.org/1999/xhtml','div');for(var node of [root,plain,html]){var map=node.attributes,watch=new MutationObserver(function(){});watch.observe(node,{attributes:true,attributeOldValue:true});node.setAttribute('MiXeD','one');var attr=node.getAttributeNode('MiXeD');if(node.getAttribute('mixed')!==null||!node.hasAttribute('MiXeD')||map[0]!==attr||attr.ownerDocument!==xml||attr.value!=='one')throw 'actual XML case and source';node.setAttribute('MiXeD','two');var records=watch.takeRecords();if(records.length!==2||records[0].attributeName!=='MiXeD'||records[0].oldValue!==null||records[1].attributeName!=='MiXeD'||records[1].oldValue!=='one'||attr.value!=='two')throw 'case-correct original observation';node.setAttributeNS('urn:attribute','p:Case','first');var named=node.getAttributeNodeNS('urn:attribute','Case');node.setAttributeNS('urn:attribute','q:Case','second');if(named!==node.getAttributeNodeNS('urn:attribute','Case')||named.prefix!=='p'||named.name!=='p:Case'||named.value!=='second'||node.getAttribute('q:Case')!==null||map.length!==2)throw 'pinned setAttributeNS preserves existing prefix and identity';records=watch.takeRecords();if(records.length!==2||records[0].attributeName!=='Case'||records[0].attributeNamespace!=='urn:attribute'||records[1].oldValue!=='first')throw 'expanded names observation';var clone=node.cloneNode(false);if(clone.getAttribute('MiXeD')!=='two'||clone.getAttributeNodeNS('urn:attribute','Case')===named||clone.namespaceURI!==node.namespaceURI)throw 'real cloned attributes';node.removeAttributeNS('urn:attribute','Case');if(named.ownerElement!==null||named.ownerDocument!==xml||named.value!=='second'||named.prefix!=='p'||map.length!==1)throw 'real detached foreign Attr';}
"#);
}
#[test]
fn inert_foreign_attribute_svg_data_refuses_activation_then_recovers_without_resource_effects(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var template=document.createElement('template');template.innerHTML='<svg><rect width="2" height="3"/></svg>';var source=template.content,root=source.firstChild,node=root.firstChild,owner=node.ownerDocument,watch=new MutationObserver(function(){});var prefix=owner.createElement('span');source.insertBefore(prefix,root);watch.observe(node,{attributes:true,attributeOldValue:true});node.setAttribute('onclick','unrequested()');node.setAttributeNS('http://www.w3.org/1999/xlink','xlink:href','https://no-inert-foreign.test/image.svg');var saved=node.getAttributeNode('onclick'),link=node.getAttributeNodeNS('http://www.w3.org/1999/xlink','href');if(saved.value!=='unrequested()'||link.value!=='https://no-inert-foreign.test/image.svg')throw 'actual legal inert data';var records=watch.takeRecords();if(records.length!==2||records[1].attributeName!=='href'||records[1].attributeNamespace!=='http://www.w3.org/1999/xlink')throw 'foreign data observed';var caught=false;try{document.getElementById('mount').appendChild(source);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||source.firstChild!==prefix||source.childNodes.length!==2||root.parentNode!==source||node.ownerDocument!==owner||saved.ownerElement!==node||link.ownerElement!==node)throw 'activation validates all actual attributes';node.removeAttribute('onclick');node.removeAttributeNS('http://www.w3.org/1999/xlink','href');node.setAttribute('fill','#123456');if(document.getElementById('mount').appendChild(source)!==source||root.ownerDocument!==document||node.ownerDocument!==document||node.getAttribute('fill')!=='#123456'||saved.ownerElement!==null||saved.value!=='unrequested()'||link.ownerElement!==null)throw 'safe real activation recovery';
"#);assert!(!page.has_navigation_request());assert!(page.take_dynamic_scripts().is_empty()&&page.take_dynamic_stylesheets().is_empty());let(a,b,c)=page.take_image_changes();assert!(a.is_empty()&&b.is_empty()&&c.is_empty());
}
